// ============================================================
// WAS ABGEGLICHEN WIRD
//
// Ein Item je Startbereich. Der Startbereich ist ein Ordner auf
// hoher Ebene; alles darunter kommt ueber den Delta-Abruf mit -
// die Schleife durch die Ordner ist die Paginierung des Abrufs,
// kein eigener Abstieg. Weitere Bereiche kommen als weiterer
// Eintrag in die Liste; der Rest des Flows laeuft je Item.
//
// Die Laufart wird gesetzt, nicht geraten: Jeder Trigger fuehrt
// ueber einen eigenen Set-Knoten hierher. Frueher wurde sie ueber
// isExecuted dreier Trigger erschlossen, weil n8n beim Handstart
// den erstbesten Trigger nimmt.
// ============================================================
const e = $input.first().json || {};
const laufart = String(e.laufart || 'delta');

const bereiche = [
  {
    bezeichnung: 'Schulungen',
    driveId: 'b!C2yhEx592Ei36yvay6U9n6Opn9Rg7v1LnJCWDZ9ZCSJEbUEViC4mS52f5_kGkuq_',
    driveName: 'Documents (Shared Documents) der Untersite Schulungen',
    siteUrl: 'https://rwgrheinland.sharepoint.com/sites/rwgintranet/Schulungen',

    // Leer heisst: ab der Wurzel der Bibliothek. Sonst die Item-ID
    // des Startordners - alles darunter kommt mit.
    startordnerId: '',

    audience: 'public'
  }
];

const vorgaben = {
  // Bilder, Videos, Verknuepfungen und Weblinks bleiben aussen vor -
  // sie machen zwei Drittel der Bibliothek aus, tragen aber keinen
  // durchsuchbaren Text.
  aktiveTypen: ['pdf', 'docx', 'doc', 'pptx', 'ppt', 'txt', 'csv', 'xlsx', 'xls', 'xlsm'],
  maxDateiMb: 40,

  // Obergrenze je Lauf. Eine grosse PDF braucht mehrere Minuten in
  // der OCR; ohne Bremse liefe der Abgleich in den Zeitrahmen.
  // Loeschungen sind billig und bleiben unbegrenzt.
  //
  // 15 ist nicht die technische Grenze, sondern die Kostenbremse: Lauf
  // 113044 las 10 Dokumente in 69 s, im Mittel 5,6 s je Stueck. Der
  // Zeitrahmen gaebe mehr her - begrenzend ist das Mistral-Kontingent.
  maxJeLauf: 15,

  // Namensfilter fuer gezielte Nacharbeit. Im Betrieb leer.
  nurDatei: '',

  verarbeiten: true,
  loeschungenMelden: true,
  zustandSchreiben: true
};

// ------------------------------------------------------------
// STARTPARAMETER VOM HANDSTART
//
// Sie haben Vorrang vor den Vorgaben. So laesst sich eine
// Urbefuellung anstossen, ohne Code zu aendern: Laufart handstart
// oeffnen, Grenze hochsetzen, starten.
//
// verarbeiten=false und zustandSchreiben=false ergeben zusammen
// einen Trockenlauf: Der Bestand wird vollstaendig verglichen und
// die Aufgabenliste gebaut, aber nichts eingelesen und der Anker
// nicht angefasst. Das ist die Gegenprobe gegen den alten Flow -
// sie kostet nichts und veraendert nichts.
// ------------------------------------------------------------
if (String(e.nurDatei || '').trim()) vorgaben.nurDatei = String(e.nurDatei).trim();
if (Number(e.maxJeLauf || 0) > 0) vorgaben.maxJeLauf = Number(e.maxJeLauf);
if (e.verarbeiten === false) vorgaben.verarbeiten = false;
if (e.zustandSchreiben === false) vorgaben.zustandSchreiben = false;

const nurBereich = String(e.nurBereich || '').trim().toLowerCase();
const gewaehlt = nurBereich
  ? bereiche.filter(b => String(b.bezeichnung).toLowerCase() === nurBereich)
  : bereiche;

if (!gewaehlt.length) {
  throw new Error('STARTBEREICH_UNBEKANNT: ' + (e.nurBereich || '(leer)'));
}

// Delta liest nur die Aenderungen seit dem Anker. Abgleich und
// Handstart lesen den vollen Bestand - derselbe Graph-Abruf, nur
// ohne Anker.
const istAbgleich = laufart !== 'delta';

return gewaehlt.map(bereich => ({ json: {
  laufart,
  istAbgleich,
  ankerIgnorieren: istAbgleich,
  lauf_id: String($execution.id),
  bereich,
  vorgaben
} }));

// Je Bereich den passenden Anker danebenlegen. Fehlt er - erster
// Lauf eines Bereichs -, bleibt er null und der Abruf holt den
// vollen Bestand.
const bereiche = $('Startbereiche').all().map(i => i.json);
const zeilen = $input.all().map(i => i.json || {});

return bereiche.map(b => {
  const zeile = zeilen.find(z => String(z.drive_id || '') === String(b.bereich.driveId)) || {};
  return { json: Object.assign({}, b, {
    delta_link: b.ankerIgnorieren ? null : (zeile.delta_link || null),
    anker_vorhanden: Boolean(zeile.delta_link)
  }) };
});

// ============================================================
// WAS IST ZU TUN?
//
//   DELTA - Graph hat gefiltert. Was kommt, hat sich geaendert.
//   ABGLEICH - der volle Bestand wird gegen die Wissensbasis
//   gehalten. Vier Befunde: fehlend, unvollstaendig, veraltet,
//   verwaist.
//
// Das Ergebnis ist eine Liste von Auftraegen - je Datei ein Objekt
// nach dem Vertrag, den RAG - SharePoint Verarbeitung annimmt.
// Nichts Binaeres: die Datei holt sich die Verarbeitung selbst.
//
// UNVOLLSTAENDIGE EINTRAEGE
// Der Ingest legt das Dokument an, bevor er die Chunks schreibt.
// Bricht ein Lauf dazwischen ab, bleibt ein Eintrag ohne Chunks
// stehen - in der Wissenssuche unsichtbar. Ohne diese Pruefung
// gaelte er als vorhanden und bliebe fuer immer leer.
//
// VORSICHT BEIM VERWAIST-BEFUND
// Als verwaist gilt nur, was eine Graph-Item-ID traegt und damit
// nachweislich aus dieser Bibliothek stammt. Dokumente aus der
// Power-Automate-Zeit bleiben unangetastet. Und geprueft wird nur,
// wenn der Lauf den vollen Bestand gesehen hat - ein auf einen
// Bereich oder einen Dateinamen eingeschraenkter Lauf sieht die
// uebrigen Dokumente nicht und darf sie nicht fuer verwaist halten.
// ============================================================
const laeufe = $('Anker zuordnen').all().map(i => i.json);
if (!laeufe.length) throw new Error('KEIN_STARTBEREICH');

const kopf = laeufe[0];
const laufart = kopf.laufart;
const istAbgleich = Boolean(kopf.istAbgleich);
const st = kopf.vorgaben || {};
const lauf_id = kopf.lauf_id;

const aktiv = new Set((st.aktiveTypen || []).map(t => String(t).toLowerCase()));
const maxBytes = Number(st.maxDateiMb || 40) * 1048576;
const nurDatei = String(st.nurDatei || '').trim().toLowerCase();

const nachDrive = {};
for (const l of laeufe) nachDrive[String(l.bereich.driveId)] = l;
const alleBereicheImLauf = laeufe.length > 0 && !nurDatei;

// ------------------------------------------------------------
// SharePoint-Bestand einsammeln und entdoppeln.
// Der Delta-Abruf liefert einen Eintrag mehrfach, wenn er sich
// mehrmals geaendert hat. Zugeordnet wird ueber die driveId am
// Eintrag; die Seite ohne eigene Eintraege erbt den zuletzt
// gesehenen Bereich.
// ------------------------------------------------------------
const spNachId = {};
const deltaLinks = {};
let letzteDrive = String(laeufe[0].bereich.driveId);

for (const s of $('SharePoint-Bestand').all()) {
  const b = s.json || {};
  for (const v of (b.value || [])) {
    const dv = (v.parentReference && v.parentReference.driveId)
      ? String(v.parentReference.driveId)
      : letzteDrive;
    if (nachDrive[dv]) letzteDrive = dv;
    spNachId[String(v.id)] = { item: v, driveId: nachDrive[dv] ? dv : letzteDrive };
  }
  if (b['@odata.deltaLink']) deltaLinks[letzteDrive] = b['@odata.deltaLink'];
}

const spEintraege = Object.keys(spNachId).map(k => spNachId[k]);

// Wissensbasis, entdoppelt
const ragNachId = {};
for (const i of $('Wissensbasis-Bestand').all()) {
  const d = i.json;
  if (d && d.doc_id) ragNachId[String(d.doc_id)] = d;
}
const ragDocs = Object.keys(ragNachId).map(k => ragNachId[k]);

// Chunkpruefung, sofern die Abfrage geantwortet hat
const mitChunks = {};
let chunkpruefung = false;
for (const i of $('Chunkzahlen laden').all()) {
  const ref = i.json && i.json.source_ref;
  if (ref) { mitChunks[String(ref)] = true; chunkpruefung = true; }
}

const ragNachName = {};
for (const d of ragDocs) {
  const n = String(d.file_name || '').toLowerCase();
  if (!n) continue;
  if (!ragNachName[n]) ragNachName[n] = [];
  ragNachName[n].push(d);
}
const istGraphKennung = (id) => /^01[A-Z0-9]{20,}$/.test(String(id || ''));

function endung(name) {
  const t = String(name || '').split('.');
  return t.length > 1 ? t.pop().toLowerCase() : '';
}
function pfadVon(it) {
  const p = (it.parentReference && it.parentReference.path) || '';
  const rein = p.replace(/^\/drives?\/[^/]+\/root:?/, '');
  return (rein ? decodeURIComponent(rein) : '') + '/' + it.name;
}
function abteilungVon(pfad) {
  const teile = String(pfad || '').split('/').filter(Boolean);
  return teile.length > 1 ? teile[0] : null;
}

function auftragAus(it, driveId, grund) {
  const lauf = nachDrive[driveId] || laeufe[0];
  const b = lauf.bereich;
  const ext = endung(it.name);
  const pfad = pfadVon(it);
  const erst = (it.createdBy && it.createdBy.user) || {};
  const letzt = (it.lastModifiedBy && it.lastModifiedBy.user) || {};
  const gleichnamig = (ragNachName[String(it.name || '').toLowerCase()] || [])
    .filter(d => String(d.doc_id) !== String(it.id));

  return {
    aktion: 'einlesen',
    grund,
    lauf_id,
    quelle: 'steuerung-' + laufart,

    item_id: it.id,
    drive_id: b.driveId,
    bereich: b.bezeichnung,
    site_url: b.siteUrl,

    filename: it.name,
    endung: ext,
    bytes: Number(it.size || 0),
    file_path: pfad,
    department: abteilungVon(pfad),
    sharepoint_url: it.webUrl || null,
    author_name: erst.displayName || null,
    author_email: erst.email || null,
    last_modified_by: letzt.displayName || null,
    created_at_sp: it.createdDateTime || null,
    last_modified_sp: it.lastModifiedDateTime || null,
    etag: it.eTag || null,
    audience: b.audience,
    alt_doc_id: gleichnamig.length === 1 ? String(gleichnamig[0].doc_id) : null
  };
}

function loeschauftrag(item_id, filename, driveId, grund) {
  const lauf = nachDrive[driveId] || laeufe[0];
  return {
    aktion: 'loeschen',
    grund,
    lauf_id,
    quelle: 'steuerung-' + laufart,
    item_id,
    filename: filename || null,
    drive_id: lauf.bereich.driveId,
    bereich: lauf.bereich.bezeichnung
  };
}

const auftraege = [];
const gesehen = {};
const uebersprungen = { falscher_typ: 0, sperrdatei: 0, zu_gross: 0, namensfilter: 0, unveraendert: 0, limit_erreicht: 0 };
let geloeschtGemeldet = 0;
let unvollstaendig = 0;

const dateien = [];
const spIds = new Set();

for (const eintrag of spEintraege) {
  const it = eintrag.item;
  if (it.deleted) {
    geloeschtGemeldet++;
    if (st.loeschungenMelden) {
      auftraege.push(loeschauftrag(it.id, it.name, eintrag.driveId, 'in SharePoint geloescht'));
    }
    continue;
  }
  if (!it.file) continue;
  dateien.push(eintrag);
  spIds.add(String(it.id));
}

for (const eintrag of dateien) {
  const it = eintrag.item;
  const ext = endung(it.name);
  gesehen[ext] = (gesehen[ext] || 0) + 1;
  if (!aktiv.has(ext)) { uebersprungen.falscher_typ++; continue; }
  // Office legt beim Oeffnen eine Sperrdatei mit Praefix ~$ an. Sie
  // traegt dieselbe Endung wie das Dokument, ist aber 162 Byte gross
  // und enthaelt nur den Namen des Bearbeiters. Ohne diesen Filter
  // laufen sie durch die OCR und landen als Leerdokumente im Bestand.
  if (String(it.name || '').indexOf('~$') === 0) { uebersprungen.sperrdatei++; continue; }
  if (nurDatei && String(it.name || '').toLowerCase().indexOf(nurDatei) === -1) { uebersprungen.namensfilter++; continue; }
  if (Number(it.size || 0) > maxBytes) { uebersprungen.zu_gross++; continue; }

  const imRag = ragNachId[String(it.id)];

  if (istAbgleich && imRag) {
    if (chunkpruefung && !mitChunks[String(it.id)]) {
      unvollstaendig++;
      auftraege.push(auftragAus(it, eintrag.driveId, 'im RAG ohne Chunks'));
      continue;
    }
    const spZeit = Date.parse(it.lastModifiedDateTime || 0) || 0;
    const ragZeit = Date.parse(imRag.last_ingested_at || 0) || 0;
    if (spZeit <= ragZeit) { uebersprungen.unveraendert++; continue; }
    auftraege.push(auftragAus(it, eintrag.driveId, 'in SharePoint neuer als im RAG'));
    continue;
  }

  auftraege.push(auftragAus(it, eintrag.driveId, istAbgleich ? 'fehlt in der Wissensbasis' : 'aus dem Delta'));
}

const verwaist = [];
let nichtZuordenbar = 0;
const verwaistGeprueft = istAbgleich && alleBereicheImLauf;

if (verwaistGeprueft) {
  for (const d of ragDocs) {
    const id = String(d.doc_id);
    if (!istGraphKennung(id)) { nichtZuordenbar++; continue; }
    if (spIds.has(id)) continue;
    verwaist.push(loeschauftrag(id, d.file_name, letzteDrive, 'liegt nicht mehr in SharePoint'));
  }
  const zuordenbar = ragDocs.length - nichtZuordenbar;
  if (zuordenbar > 0 && verwaist.length > Math.max(5, zuordenbar * 0.2)) {
    throw new Error('SICHERUNG: ' + verwaist.length + ' von ' + zuordenbar + ' zuordenbaren Dokumenten gaelten als verwaist. Abgleich abgebrochen.');
  }
  for (const v of verwaist) auftraege.push(v);
}

// Unvollstaendige zuerst: Sie sind bereits angelegt und blockieren
// sonst dauerhaft einen Platz im Bestand.
const max = Number(st.maxJeLauf || 20);
const loeschen = auftraege.filter(a => a.aktion === 'loeschen');
const luecken = auftraege.filter(a => a.aktion !== 'loeschen' && a.grund === 'im RAG ohne Chunks');
const uebrige = auftraege.filter(a => a.aktion !== 'loeschen' && a.grund !== 'im RAG ohne Chunks');
const einlesen = luecken.concat(uebrige);
if (einlesen.length > max) uebersprungen.limit_erreicht = einlesen.length - max;
const liste = loeschen.concat(einlesen.slice(0, max));

const formate = Object.keys(gesehen).sort((a, b) => gesehen[b] - gesehen[a]).map(e => e + ':' + gesehen[e]);

return [{ json: {
  _lauf: {
    laufart,
    lauf_id,
    bereiche: laeufe.map(l => l.bereich.bezeichnung),
    items_im_bestand: spEintraege.length,
    dateien: dateien.length,
    rag_dokumente: ragDocs.length,
    chunkpruefung_moeglich: chunkpruefung,
    rag_mit_chunks: Object.keys(mitChunks).length,
    rag_nicht_zuordenbar: nichtZuordenbar,
    formate_gesehen: formate,
    geloescht_gemeldet: geloeschtGemeldet,
    verwaist_geprueft: verwaistGeprueft,
    verwaist_gefunden: verwaist.length,
    unvollstaendig_gefunden: unvollstaendig,
    fehlend_gesamt: einlesen.length,
    einzulesen: Math.min(einlesen.length, max),
    zu_loeschen: loeschen.length,
    aufgaben_gesamt: liste.length,
    uebersprungen,
    delta_links: deltaLinks,
    delta_link_erhalten: Object.keys(deltaLinks).length > 0,
    vollabruf: Boolean(kopf.ankerIgnorieren),
    max_je_lauf: max
  },
  auftraege: liste
} }];

// Je Bereich eine Zeile. Der Anker rueckt nur vor, wenn tatsaechlich
// verarbeitet wurde - ein Trockenlauf laesst ihn stehen, sonst gingen
// ungelesene Aenderungen verloren.
const lauf = $('Aufgaben bestimmen').first().json._lauf;
const bereiche = $('Anker zuordnen').all().map(i => i.json.bereich);
const links = lauf.delta_links || {};

return bereiche
  .filter(b => links[String(b.driveId)])
  .map(b => ({ json: {
    drive_id: b.driveId,
    drive_name: b.driveName,
    delta_link: links[String(b.driveId)],
    letzte_items: lauf.items_im_bestand,
    letzte_uebergeben: lauf.aufgaben_gesamt
  } }));

// ============================================================
// WAS DER LAUF GETAN HAT
//
// In einer splitInBatches-Schleife liefert $('Node').all() nur den
// letzten Durchlauf. Der zweite Parameter ist der Durchlaufindex; er
// wird hochgezaehlt, bis kein Durchlauf mehr kommt.
//
// Frueher mussten dafuer fuenf verschiedene Enden der Verarbeitung
// eingesammelt werden. Die Verarbeitung liefert jetzt genau eine
// Antwortform - gesammelt wird nur noch an einer Stelle.
// ============================================================
function sammle(name) {
  const raus = [];
  for (let i = 0; i < 2000; i++) {
    let items;
    try { items = $(name).all(0, i); } catch (e) { break; }
    if (!items || !items.length) break;
    for (const it of items) raus.push(it.json || {});
  }
  return raus;
}

const kopf = $('Anker zuordnen').first().json;
const lauf = $('Aufgaben bestimmen').first().json._lauf || {};
const auftraege = $('Aufgaben bestimmen').first().json.auftraege || [];

const alle = sammle('Verarbeitung aufrufen');

// Bei Fehler laeuft die Schleife weiter; der Knoten legt dann ein
// Item mit error ab, statt einer Antwort nach dem Vertrag.
const geplatzt = alle.filter(e => e && e.error !== undefined && e.error !== null);
const ergebnisse = alle.filter(e => e && (e.error === undefined || e.error === null));

const mit = (s) => ergebnisse.filter(e => e.status === s);
const eingelesen = mit('eingelesen');
const unveraendert = mit('unveraendert');
const geloescht = mit('geloescht');
const zurueckgestellt = mit('zurueckgestellt');
const uebersprungen = mit('uebersprungen');
const fehler = mit('fehler').concat(geplatzt);

function kurz(e) {
  const name = e.filename || e.doc_id || '?';
  const grund = e.grund || e.roh_status || (e.error && (e.error.message || e.error)) || 'unbekannt';
  return name + ': ' + String(grund).slice(0, 160);
}

const mappen = ergebnisse.filter(e => e.blaetter_tabelle || e.blaetter_text);

return [{ json: {
  laufart: lauf.laufart,
  lauf_id: lauf.lauf_id,
  bereiche: lauf.bereiche,

  gesehen: {
    items_im_bestand: lauf.items_im_bestand,
    dateien: lauf.dateien,
    rag_dokumente: lauf.rag_dokumente,
    rag_nicht_zuordenbar: lauf.rag_nicht_zuordenbar,
    formate: lauf.formate_gesehen
  },

  geplant: {
    einzulesen: lauf.einzulesen,
    zu_loeschen: lauf.zu_loeschen,
    verwaist_geprueft: lauf.verwaist_geprueft,
    verwaist_gefunden: lauf.verwaist_gefunden,
    geloescht_gemeldet: lauf.geloescht_gemeldet,
    max_je_lauf: lauf.max_je_lauf,
    uebersprungen: lauf.uebersprungen
  },

  ergebnis: {
    neu_oder_geaendert: eingelesen.length,
    unveraendert: unveraendert.length,
    geloescht: geloescht.length,
    uebersprungen: uebersprungen.length,
    zurueckgestellt: zurueckgestellt.length,
    fehler: fehler.length,
    antworten_gesamt: alle.length
  },

  woerter_eingelesen: eingelesen.reduce((s, e) => s + (Number(e.woerter) || 0), 0),
  chunks_geschrieben: eingelesen.reduce((s, e) => s + (Number(e.chunks) || 0), 0),
  bilder_erkannt: eingelesen.reduce((s, e) => s + (Number(e.bilder) || 0), 0),

  arbeitsmappen: mappen.map(m => ({
    datei: m.filename,
    als_tabelle: m.blaetter_tabelle,
    als_text: m.blaetter_text
  })),

  uebersprungene: uebersprungen.map(kurz),
  zurueckgestellte: zurueckgestellt.slice(0, 20).map(kurz),
  fehlerdetails: fehler.slice(0, 10).map(kurz),

  anker_geschrieben: Boolean(kopf.vorgaben.zustandSchreiben) && Boolean(lauf.delta_link_erhalten),
  auftragsliste: auftraege.slice(0, 40).map(a => a.aktion + ' | ' + (a.grund || '-') + ' | ' + (a.filename || a.item_id))
} }];

parameters.text:
=[ZURUECKGESTELLT] {{ $workflow.name }}

Der Abgleich ist sauber durchgelaufen, aber {{ $json.ergebnis.zurueckgestellt }} Datei(en) blieben liegen.

Eingelesen:      {{ $json.ergebnis.neu_oder_geaendert }}
Zurueckgestellt: {{ $json.ergebnis.zurueckgestellt }}
Fehler:          {{ $json.ergebnis.fehler }}

{{ $json.zurueckgestellte.join(String.fromCharCode(10)).replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;') }}

Lauf:    {{ $execution.id }}
